r.append(R(7300874,"अफ़गान सलाद","इसे सलाता के नाम से भी जाना जाता है। टमाटर, गाजर और प्याज़ का यह ताज़गी भरा और रंग-बिरंगा सलाद हल्का और कुरकुरा है।","4","245 ग्राम",
["2-3 बड़े टमाटर, बारीक कटे हुए (260 ग्राम)","50 ग्राम ताज़ा धनिया, मोटा कटा हुआ","20 ग्राम ताज़ा पुदीना, मोटा कटा हुआ","1 नीबू, रस और बारीक कद्दूकस किया हुआ ज़ेस्ट","1 बड़ा चम्मच एक्स्ट्रा-वर्जिन जैतून का तेल","एक अच्छी चुटकी काली मिर्च","1 बड़ा लाल प्याज़, बारीक चौकोर कटा हुआ (180 ग्राम)","आधा खीरा, बारीक चौकोर कटा हुआ (160 ग्राम)","2 बड़ी गाजर, कद्दूकस की हुई (250 ग्राम)"],
["टमाटरों को धनिया, पुदीना, नीबू के रस, जैतून के तेल और काली मिर्च के साथ कटोरे में डालें और अच्छी तरह मिलाएँ।","लाल प्याज़, खीरा और गाजर डालें। अच्छी तरह मिलाएँ और परोसें।"],
["अजमोद, तुलसी या सोआ जैसी अलग जड़ी-बूटियों के साथ आज़माएँ।","ग्रिल किए हुए मांस, मछली, पोल्ट्री या टोफू के साथ परोसें।","बुफ़े के हिस्से के रूप में या लंच बॉक्स के लिए बढ़िया।",FV(2)]))
r.append(R(7305915,"फूलगोभी स्टर फ्राई","यह स्वादिष्ट व्यंजन सिर्फ़ 30 मिनट में तैयार हो जाता है और एक व्यक्ति के लिए हफ़्ते के बीच के दिनों का बिल्कुल सही भोजन विकल्प है।","1","380 ग्राम",
["1½ छोटा चम्मच तिल","1 छोटा प्याज़, पतला कटा हुआ (बिना छिले लगभग 60 ग्राम)","1 छोटा चम्मच रेपसीड तेल","60 ग्राम लीक, पतला कटा हुआ","1 लहसुन की फांक, कुचली हुई","1 छोटा चम्मच ताज़ा कद्दूकस किया अदरक","250 ग्राम फूलगोभी के फूल","1 कैलोरी वाले तेल की 5-6 स्प्रे","1 छोटा चम्मच टबैस्को या 1 छोटा चम्मच श्रीराचा हॉट सॉस","1 बड़ा चम्मच हरी प्याज़ (स्प्रिंग अनियन), बारीक कटी हुई","1 बड़ा चम्मच धनिया, हाथ से फाड़ा हुआ"],
["एक छोटा फ्राइंग पैन गरम करें और तिल को 1-2 मिनट तक हल्का भूरा होने और खुशबू आने तक बिना तेल के भूनें। एक तरफ़ रख दें।","पैन में तेल, प्याज़ और लीक डालें, ढककर बहुत धीमी आँच पर 5 मिनट तक नरम होने तक बार-बार चलाते हुए पकाएँ। लहसुन और अदरक डालें। 1 मिनट और पकाएँ।","फूलगोभी पर 1 कैलोरी वाले तेल की अच्छी स्प्रे करें, कम से कम 5-6 बार, और 3 छोटे चम्मच पानी के साथ प्याज़ वाले पैन में डालें। मध्यम आँच पर 5-6 मिनट तक बीच-बीच में चलाते हुए पकाएँ, जब तक कि फूल भूरे होने न लगें।","टबैस्को या श्रीराचा डालें, मिलाएँ और 1 मिनट और पकाएँ। कटोरे में चम्मच से निकालें, हरी प्याज़, धनिया और तिल छिड़कें और परोसें।"],
[FV(4)]))
r.append(R(7308141,"नट रोस्ट","यह शाकाहारी मुख्य व्यंजन क्लासिक रोस्ट डिनर की संगत के साथ बिल्कुल सही मेल खाता है।","8","166 ग्राम",
["100 ग्राम बटरनट स्क्वैश, उबला हुआ, फिर मैश किया हुआ","1 बड़ा चम्मच रेपसीड तेल","1 प्याज़, बारीक कटा हुआ","1 लाल शिमला मिर्च, बारीक कटी हुई","2 लहसुन की फांकें, कुचली हुई","150 ग्राम मिले-जुले बिना नमक वाले मेवे (बादाम, अखरोट, ब्राज़ील नट्स, हेज़लनट्स)","2 अंडे, हल्के फेंटे हुए","150 ग्राम पिसे बादाम","200 ग्राम का पैकेट पके हुए चेस्टनट, बारीक कटे हुए","चुटकी भर काली मिर्च","2 बड़े चम्मच पानी","चुटकी भर पिसा जायफल","100 ग्राम पालक, पका हुआ और अच्छी तरह निचोड़ा हुआ (130 ग्राम जमा हुआ और पिघलाया हुआ, या 250 ग्राम ताज़ा)","25 ग्राम सूखी क्रैनबेरी"],
["ओवन को 175°C/गैस 3 पर पहले से गरम करें। बटरनट स्क्वैश को छीलें, बीज निकालें और टुकड़ों में काटें। पानी के पैन में डालकर उबाल लाएँ। 10-15 मिनट तक नरम होने तक उबालें। जब गूदा नरम हो जाए, तो पानी निकालकर मैश करें और एक तरफ़ रख दें।","इस बीच, मध्यम आँच पर पैन में 1 छींटा तेल डालें, फिर प्याज़ डालें और नियमित रूप से चलाएँ। जब वह भूरा होने लगे, तो लाल शिमला मिर्च डालें और 4-5 मिनट और पकाएँ। लहसुन डालें, मिलाएँ और आँच से उतारकर ठंडा होने दें।","मेवों को 3 ढेरों में बाँटें। एक तिहाई मेवे साबुत रखकर एक तरफ़ रख दें। दूसरे तिहाई को मोटा काटें और आख़िरी तिहाई को बारीक काटें।","एक कटोरे में अंडे, पिसे बादाम, प्याज़, लाल शिमला मिर्च, बारीक कटे और मोटे कटे मेवे, चेस्टनट, काली मिर्च, पानी और जायफल डालें। अच्छी तरह मिलाएँ।","1 पाउंड के लोफ़ टिन के चारों ओर बचा हुआ तेल लगाएँ और उसमें ग्रीसप्रूफ़ पेपर बिछाएँ।","अंडे के मिश्रण का दो-तिहाई हिस्सा डालें और उसे टिन के चारों ओर दबाकर परत बनाएँ, बीच में भरावन के लिए जगह छोड़ दें।","बीच में बटरनट स्क्वैश डालें, फिर पालक की परत लगाएँ। अंत में क्रैनबेरी छिड़कें।","इसके बाद, ढक्कन बनाने के लिए अंडे का बचा हुआ मिश्रण ध्यान से डालें और अलग रखे साबुत मेवे छिड़कें, उन्हें हल्के से ऊपरी परत में दबाएँ।","फ़ॉइल के एक टुकड़े से ढकें और लोफ़ को एक और बड़ी ओवन डिश में रखें। लोफ़ टिन की आधी ऊँचाई तक पानी भरें। (इस तकनीक को बेन-मारी कहते हैं।) ओवन में 30 मिनट तक पकाएँ, फिर फ़ॉइल हटाएँ और 10 मिनट और पकाएँ।","ओवन से निकालें, प्लेट पर पलटकर निकालें और परोसें।"],
["इस रेसिपी के मेवे इस व्यंजन को वसा में ज़्यादा बनाते हैं। लेकिन ज़्यादातर मेवों में पाई जाने वाली वसा उन्हें असंतृप्त वसा का अच्छा स्रोत बनाती है, जो आपके हृदय के स्वास्थ्य के लिए अच्छी है। मेवे प्रोटीन और फ़ाइबर में भी ज़्यादा होते हैं।","अगर आप मेवे खा रहे हैं, तो उन्हें बिना नमक के खाना बेहतर है।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फिर फ्रिज में या माइक्रोवेव में पिघलाएँ और पूरी तरह भाप निकलने तक गरम होने तक दोबारा गरम करें।",FV(0)]))
r.append(R(7308711,"चॉकलेट और केला मूस","यह वीगन मिठाई घर पर आज़माने के लिए चॉकलेट के स्वाद वाला बिल्कुल सही व्यंजन है।","4","128 ग्राम",
["75 ग्राम डेयरी-मुक्त डार्क चॉकलेट, मोटी कटी हुई","2 बड़े चम्मच पिस्ता, मोटे कटे हुए","2 छोटे चम्मच वनीला एक्सट्रैक्ट","200 ग्राम पौधे-आधारित ग्रीक शैली का दही","2 बड़े चम्मच कोको पाउडर","1 बड़ा केला, छिला हुआ"],
["चॉकलेट को हल्के उबलते पानी के पैन पर रखे कटोरे में डालें। पिघलने तक हल्के से गरम करें। पिघली हुई चॉकलेट के 2 बड़े चम्मच को नॉन-स्टिक बेकिंग पेपर के टुकड़े पर पतला फैलाएँ। ढकने के लिए ऊपर से पिस्ता छिड़कें। फ्रिज में ठंडा करें।","केले को फ़ूड प्रोसेसर में वनीला एक्सट्रैक्ट, 6 बड़े चम्मच दही और कोको पाउडर के साथ डालें। बची हुई पिघली चॉकलेट डालें और 2 बड़े चम्मच उबलता पानी मिलाएँ। चिकना और गाढ़ा होने तक ब्लेंड करें। अलग-अलग गिलासों में चम्मच से डालें और कम से कम 2 घंटे के लिए ठंडा करें।","परोसने के लिए तैयार होने पर, हर मिठाई पर बचे हुए दही का 1 बड़ा चम्मच डालें। मिठाइयों को सजाने के लिए चॉकलेट और पिस्ता की पट्टी को टुकड़ों में तोड़ लें।"],
[]))
r.append(R(7308963,"लैम्ब टैगीन","पूरे परिवार का पेट भरने के लिए मध्य-पूर्वी स्वाद से प्रेरित एक भरपेट व्यंजन।","4","450 ग्राम",
["एक छींटा जैतून का तेल","2 प्याज़, फांकों में कटे हुए","350 ग्राम दुबला भेड़ का मांस, टुकड़ों में कटा हुआ","2 गाजर, कटी हुई","1 पीली शिमला मिर्च, कटी हुई","1 x 400 ग्राम का डिब्बा कटे हुए टमाटर","1 ढेर वाला छोटा चम्मच सूखा पुदीना","1 ढेर वाला छोटा चम्मच पिसी दालचीनी","1 ढेर वाला छोटा चम्मच जीरा","एक चौथाई छोटा चम्मच चिली फ्लेक्स","चुटकी भर नमक","50 ग्राम सूखी खुबानी, आधी कटी हुई","1 x 400 ग्राम का डिब्बा छोले, छाने हुए"],
["पैन में तेल डालें, फिर प्याज़ डालें और 3 मिनट तक भूरा होने तक पकाएँ। भेड़ का मांस डालें और बाहर से भूरा करने के लिए दो मिनट और चलाएँ।","गाजर, पीली शिमला मिर्च, टमाटर, पुदीना, दालचीनी, जीरा, चिली फ्लेक्स, 200 मिलीलीटर पानी और नमक डालें। हल्का उबाल लाएँ, आँच कम करें, ढक्कन लगाएँ और नियमित रूप से चलाते हुए 30 मिनट तक हल्की आँच पर पकाएँ।","खुबानी और छोले डालें, और 15 मिनट और हल्की आँच पर पकाएँ।","कूसकूस, चावल या फ़्लैटब्रेड और सलाद के साथ परोसें।"],
["सबसे किफ़ायती तरीके के लिए, सूखे छोले इस्तेमाल करके देखें। पैकेट के निर्देशों के अनुसार पूरे पैकेट के छोलों को भिगोकर पकाएँ, फिर उन्हें फ्रीज़ कर दें। आपको जितनी ज़रूरत हो उतनी पिघलाकर स्ट्यू, सूप, करी और सलाद जैसे हर तरह के व्यंजनों में डाल सकते हैं।",FV(4)]))
r.append(R(7309643,"चिकन ब्रावास","गाढ़े टमाटर, लहसुन, मिर्च और स्मोक्ड पेपरिका में लिपटे रसीले, मसालेदार चिकन के टुकड़े। तापस के हिस्से के रूप में बाँटें, या सलाद के साथ रैप में परोसें।","30","50 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","4 बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट (1 x 650 ग्राम का पैकेट), टुकड़ों में कटे हुए","6 लहसुन की फांकें, कटी हुई","1 x 400 ग्राम का डिब्बा कटे हुए टमाटर","1 बड़ा चम्मच टमाटर प्यूरी","2 ढेर वाले छोटे चम्मच स्मोक्ड पेपरिका","1 मिर्च, बारीक कटी हुई","10 लिटिल जेम लेट्यूस के पत्ते","कॉकटेल स्टिक"],
["एक बड़े पैन में तेल डालें।","चिकन डालें और बीच-बीच में चलाते हुए 4-5 मिनट तक चारों तरफ़ से हल्का भूरा होने तक पकाएँ।","लहसुन डालें और 2 मिनट पकाएँ, फिर टमाटर, प्यूरी, पेपरिका और मिर्च डालें। हल्का उबाल लाएँ, फिर आँच कम करें, ढक्कन लगाएँ और नियमित रूप से चलाते हुए 10 मिनट तक हल्की आँच पर पकाएँ। ढक्कन हटाएँ, अच्छी तरह चलाएँ और लगभग सारा तरल भाप बनकर चिकन पर पूरी तरह लिपट जाने तक हल्की आँच पर पकाएँ।","लेट्यूस को परोसने वाली डिश के किनारे सजाएँ, चिकन के टुकड़ों को बीच में ढेर करें और उन्हें पिरोने के लिए कॉकटेल स्टिक लगाएँ।"],
["अंत में डिश को हल्की आँच पर पकाएँ क्योंकि उद्देश्य सॉस बनाना नहीं, बल्कि चिकन पर गाढ़ी परत बनाना है।","आप इसे चिकन की जगह सूअर के मांस या सख़्त मछली से बना सकते हैं। शाकाहारी संस्करण के लिए, टोफू के साथ आज़माएँ।"]))
r.append(R(7310597,"गरम दाल और बकरी के चीज़ का सलाद","इस झटपट और आसान स्टार्टर या साइड डिश में सरल ताज़े स्वाद मिलते हैं, जिसमें प्रति सर्विंग 200 कैलोरी से कम है।","8","138 ग्राम",
["2 लाल शिमला मिर्च, आधी कटी और बीज निकाली हुई","2 बड़े चम्मच जैतून का तेल","2 बड़े चम्मच ताज़ा ऑरिगैनो, कटा हुआ (या 1 छोटा चम्मच सूखा)","1 गुच्छा हरी प्याज़ (स्प्रिंग अनियन), कटी हुई","800 ग्राम का डिब्बा हरी दाल, छनी और धोई हुई","1 बड़ा चम्मच वाइन/साइडर सिरका","1 लहसुन की फांक, कुचली हुई","150 ग्राम बकरी का चीज़, चूरा किया हुआ","1 छोटा चम्मच कटा हुआ ताज़ा अजमोद (पार्सले)"],
["ग्रिल को तेज़ पर पहले से गरम करें।","शिमला मिर्च को फ़ॉइल बिछी बेकिंग ट्रे पर छिलके वाली तरफ़ ऊपर करके रखें और 7-8 मिनट तक ग्रिल करें, जब तक कि छिलके काले न हो जाएँ।","प्लास्टिक के बैग में डालें, बंद करें और एक तरफ़ रख दें।","जब छूने लायक ठंडी हो जाएँ (लगभग 10 मिनट), तो छिलके उतारें और गूदे को काट लें।","इस बीच, नॉन-स्टिक फ्राइंग पैन में तेल गरम करें।","ऑरिगैनो, हरी प्याज़ और दाल डालें और 2 मिनट तक भूनें।","अजमोद को छोड़कर बाकी सामग्री डालें, गरम करें, मसाला डालें और फिर परोसने की डिश में निकालें।","गरम परोसें, ऊपर से अजमोद छिड़कें।"],
["अगर आप चाहें तो बकरी के चीज़ की जगह फ़ेटा चीज़ भी अच्छा लगता है।","आप हरी दाल की जगह प्यूय दाल इस्तेमाल कर सकते हैं, ऐसी दाल देखें जो सिर्फ़ पानी में डिब्बाबंद हो, अतिरिक्त नमक और चीनी के साथ नहीं।",FV(1)]))
r.append(R(7313231,"हरी मिर्च डिप के साथ शकरकंद क्रैब केक","शकरकंद के साथ मसालेदार क्रैब केक एक बिल्कुल सही पार्टी व्यंजन बनाते हैं।","25","29 ग्राम",
["200 ग्राम शकरकंद, उबली और मैश की हुई","1 बड़ा चम्मच मैदा (साथ में छिड़कने के लिए थोड़ा और)","1 अंडा, फेंटा हुआ","एक अच्छी चुटकी काली मिर्च","20 ग्राम ताज़ा सोआ (डिल), कटा हुआ","3 हरी प्याज़ (स्प्रिंग अनियन), बारीक कटी हुई","200 ग्राम पका हुआ केकड़े का मांस, गहरा और भूरा","1 नीबू का कद्दूकस किया हुआ ज़ेस्ट (साथ में परोसने के लिए फांकें)","2 छोटे चम्मच रेपसीड तेल",("सालसा के लिए","2 टमाटर, मोटे कटे हुए"),("सालसा के लिए","1 ढेर वाला बड़ा चम्मच टमाटर प्यूरी"),("सालसा के लिए","1 हरी मिर्च, बीज निकाली हुई और बहुत बारीक कटी हुई")],
["आलू तैयार करें और ठंडा होने दें।","मैश किए हुए आलू में मैदा, अंडा, काली मिर्च और सोआ डालें और अच्छी तरह मिलाएँ।","हरी प्याज़ और केकड़ा मिलाएँ, एक साथ मिलाएँ फिर लगभग 1 सेमी मोटी छोटी टिक्कियाँ बनाएँ, फिर उन पर मैदा छिड़कें।","नॉन-स्टिक पैन में 1 छोटा चम्मच तेल डालें, 1-2 मिनट तक तलें और बराबर पकाने के लिए दो-तीन बार ध्यान से पलटें (कुल मिलाकर लगभग 6 मिनट) जब तक कि हल्की सुनहरी और सख़्त न हो जाएँ, और यह सुनिश्चित करें कि टिक्कियाँ अंदर तक पक गई हों।","इस बीच, सालसा के लिए टमाटरों को टमाटर प्यूरी के साथ ब्लेंड करें और हरी मिर्च मिलाएँ।"],
["स्वाद के लिए सफ़ेद और गहरे केकड़े का मिश्रण आदर्श है। इसे सैल्मन और/या कटे झींगों के साथ बनाकर देखें।",FV(0)]))
r.append(R(7313285,"स्वैम्प जूस में विचेटी ग्रब्स","खसखस के दानों से सजे आलू के न्योकी विश्वसनीय ग्रब्स (इल्लियाँ) बनाते हैं। स्वादिष्ट मटर और पालक की सॉस के साथ जोड़कर हैलोवीन पार्टी के लिए एक आसान, सेहतमंद नाश्ता बनाएँ।","4","172 ग्राम",
["400 ग्राम का पैकेट ताज़े आलू के न्योकी","1 छोटा चम्मच जैतून का तेल","2 छोटे चम्मच खसखस","100 ग्राम जमे हुए मटर","75 ग्राम कटा हुआ जमा पालक (पिघलाया हुआ और तरल निचोड़ा हुआ)","2 टहनी पुदीना, कटा हुआ","100 मिलीलीटर स्किम्ड दूध"],
["न्योकी को पैकेट के निर्देशों के अनुसार पकाएँ (आमतौर पर उबलते पानी में लगभग 1-2 मिनट)। जैसे ही वे ऊपर तैरने लगें, तैयार हैं।","पानी निकालें और तेल में हल्के से उछालें। खसखस छिड़कें, यह सुनिश्चित करें कि वे समान रूप से लिपट जाएँ। एक तरफ़ रख दें।","स्वैम्प जूस बनाने के लिए, मटर, पालक, पुदीना और दूध को एक पैन में डालें, उबाल तक लाएँ और 3-4 मिनट तक पकाएँ। आँच से उतारें और चिकनी सॉस बनाने के लिए ब्लेंड करें।","सॉस को डिश में डालें और न्योकी डालें। परोसने के लिए कॉकटेल स्टिक का उपयोग करें।"],
["अगर आपके पास पुदीना नहीं है तो आप तुलसी या अजमोद जैसी दूसरी जड़ी-बूटियाँ इस्तेमाल कर सकते हैं। अगर आप इसे थोड़ा मसालेदार बनाना चाहते हैं तो थोड़ी मिर्च या करी पेस्ट डालें।","यह बाँटने के लिए बेहतरीन कैनापे बनाता है। एक पैकेट में आमतौर पर लगभग 30 न्योकी होते हैं। कॉकटेल स्टिक के साथ परोसें।","आप सॉस को गरम या ठंडा परोस सकते हैं। न्योकी के साथ टमाटर की सॉस भी अच्छी लगेगी।",FV(0)]))
r.append(R(7314971,"हरीसा टमाटर टार्ट","यह स्वादिष्ट टार्ट नमक और संतृप्त वसा में कम है और गर्मियों के दोपहर के भोजन या पिकनिक के लिए बढ़िया है।","4","310 ग्राम",
["180 ग्राम 0% वसा वाला सादा ग्रीक दही, साथ में परोसने के लिए 4 बड़े चम्मच","180 ग्राम सेल्फ़-राइज़िंग आटा, साथ में छिड़कने के लिए 2 छोटे चम्मच","1/2 छोटा लाल प्याज़, पतला कटा हुआ","4 टमाटर, मोटे कटे हुए","4 छोटे चम्मच हरीसा पेस्ट","2 छोटे चम्मच रेड वाइन सिरका","1 छोटा चम्मच जैतून का तेल","1 बड़ा चम्मच कटा हुआ ताज़ा फ़्लैट-लीफ़ अजमोद (पार्सले)","परोसने के लिए रॉकेट (अरुगुला) पत्तियाँ"],
["ओवन को 200°C, फ़ैन 180°C, गैस मार्क 6 पर पहले से गरम करें, और 2 बेकिंग ट्रे में बेकिंग पेपर बिछाएँ।","दही और आटे को मिक्सिंग बाउल में डालें और अच्छी तरह मसाला डालें। नरम आटा बनने तक मिलाएँ।","काम की सतह पर आटा छिड़कें। पिज़्ज़ा के आटे को 4 टुकड़ों में बाँटें और हर टुकड़े को 15 सेमी के गोले में बेलें। तैयार बेकिंग ट्रे पर रखें, प्याज़ बिखेरें फिर ऊपर से टमाटर के स्लाइस रखें।","एक छोटे जग में हरीसा पेस्ट, सिरका और तेल मिलाएँ, फिर अच्छी तरह मसाला डालें। हरीसा के मिश्रण को टमाटर के स्लाइस पर छिड़कें या ब्रश से लगाएँ, फिर टार्ट को 20 मिनट तक बेक करें, जब तक कि आटा कुरकुरा और सुनहरा न हो जाए।","ऊपर से दही डालें, कटा अजमोद बिखेरें और किनारे पर रॉकेट के साथ परोसें।"],
[]))
r.append(R(7315197,"एशियाई सैल्मन फ़िलेट","धनिये और हरी प्याज़ से सजा एक हल्का, स्वादिष्ट व्यंजन।","6","141 ग्राम",
["6 टुकड़े बिना त्वचा के सैल्मन फ़िलेट (प्रत्येक लगभग 125 ग्राम)",("मैरिनेड के लिए","1 बड़ा चम्मच कम नमक वाला सोया सॉस"),("मैरिनेड के लिए","2 छोटे चम्मच तिल का तेल"),("मैरिनेड के लिए","चुटकी भर चिली फ्लेक्स"),("मैरिनेड के लिए","1 छोटा चम्मच ताज़ा अदरक, कद्दूकस किया हुआ"),("मैरिनेड के लिए","2 छोटे चम्मच बहता हुआ शहद"),("सजावट के लिए","1 बड़ा चम्मच ताज़ा कटा धनिया"),("सजावट के लिए","4 हरी प्याज़ (स्प्रिंग अनियन), बारीक कटी हुई")],
["मैरिनेड की सारी सामग्री को गैर-धातु के कटोरे में डालें और अच्छी तरह मिलाएँ।","सैल्मन फ़िलेट डालें, उन्हें मैरिनेड में लपेटें और स्वाद रचने-बसने के लिए एक तरफ़ रख दें।","मध्यम आँच पर 3-4 मिनट तक पकाएँ, बचा हुआ मैरिनेड डालें, पलटें और दूसरी तरफ़ 3-4 मिनट तक अंदर तक अच्छी तरह पकने तक पकाएँ।","परोसने से पहले धनिया और हरी प्याज़ बिखेरें।"],
["यह मैकेरल, रिवर कॉब्लर या ताज़ा टूना जैसे दूसरे मछली के फ़िलेट के साथ भी अच्छा बनता है।","फ्रीज़ करने के निर्देश: पकने के बाद फ्रीज़ करने के लिए उपयुक्त। फ्रिज में पिघलाएँ और पूरी तरह भाप निकलने तक दोबारा गरम करें।",FV(0)]))
